about_disclaimer_title: "Sorumluluk reddi",
about_disclaimer_purpose: "ps5upload yalnızca araştırma, eğitim, birlikte çalışabilirlik ve homebrew geliştirme amaçlarıyla sunulmaktadır. Sony Interactive Entertainment Inc. ile bağlantılı değildir, onun tarafından desteklenmez ve onunla ilişkili değildir. “PlayStation” ve “PS5”, Sony Interactive Entertainment Inc. şirketinin ticari markalarıdır ve burada yalnızca tanımlama amacıyla kullanılmıştır.",
about_disclaimer_piracy: "Yalnızca sahibi olduğunuz donanımla ve yasal olarak sahip olduğunuz içerikle kullanın. Kullanma hakkına sahip olmadığınız yazılımları kopyalamak, dağıtmak veya çalıştırmak için kullanılmamalıdır.",
about_disclaimer_risk: "Bu yazılım, hiçbir garanti verilmeksizin “olduğu gibi” sunulmaktadır. Değiştirilmiş bir konsolu çalıştırmak konsola kalıcı zarar verebilir, kayıtları ve lisansları geri dönülmez biçimde yok edebilir ve hesabınızın ya da konsolunuzun yasaklanmasına yol açabilir. Tümüyle kendi sorumluluğunuzda kullanırsınız ve sonuçların tam sorumluluğunu kabul edersiniz. Başlamadan önce kaybetmeyi göze alamayacağınız her şeyi yedekleyin.",
