imgbrowse_explain: "ps5upload'ın okuduğu herhangi bir oyun görüntüsüne veya pakete (.exfat, .ffpkg, .ffpfs, .ffpfsc ya da hata ayıklama anahtarıyla yapılmış bir .pkg) bağlamadan, herhangi bir bilgisayarda göz atın. Bir dosyayı veya klasörü bilgisayara kaydedin ya da dosyaları değiştirip düzenlenmiş bir kopya yazın: açtığınız görüntü asla değişmez.",
