localimage_explain: "Görüntüyü bu bilgisayarda normal bir sürücü olarak açar; böylece içindeki dosyaları — örneğin yama dosyalarını — Finder veya Dosya Gezgini ile tıpkı bir USB bellekteki gibi ekleyebilir, değiştirebilir ve silebilirsiniz. Değişiklikler doğrudan görüntü dosyasına kaydedilir. ps5upload görüntüye hiçbir zaman kendisi yazmaz; bunu işletim sisteminiz yapar. İşiniz bittiğinde buradan çıkarın.",
