"pkglib.installAll.what": "“Tümünü yükle” nedir?",
"pkglib.installAll.whatBody": "“Tümünü yükle”, hazır olan her paketi sırayla çalıştırır: temel oyun → güncellemeler → DLC. Aynı sürümün iki güncellemesi (veya çakışan iki DLC paketi) varsa, bu konsolun hangisini yükleyeceğini seçmek için her satırdaki onay kutusunu kullanın — grup başına yalnızca bir tane. O grubu tamamen dışarıda bırakmak için işareti kaldırın. Tek bir satırdaki Yükle düğmesi her zaman yalnızca o paketi yükler.",
