library_edit_files_short: "Dosyaları düzenle",

library_images_capabilities: "Oynamak için bağla ya da içindekini değiştirmek için Dosyaları düzenle'yi kullan — DLC ekleme, varlık değiştirme veya backport yaması uygulama. Değişiklikler doğrudan imaja yazılır.",

library_edit_modal_title: "\"{name}\" düzenle",
library_edit_modal_intro: "Çalışırken nereye bağlanacağını seç. Bu süre boyunca ShadowMount+ içinden çıkarılır ve bitirdiğinde geri konur — o zamana kadar oyun PS5 ana ekranında görünmez.",
library_mount_tooltip_smp: "Bu imajı ShadowMount+'a devret; onu bağlayıp kaydeder, böylece oynayabilirsin (salt okunur)",



helper_mismatch_title: "PS5 yardımcısı v{payload}, bu uygulama ise v{app}",
helper_mismatch_send: "Yardımcıyı gönder",
helper_mismatch_body_v3: "PS5'in kendisinde yapılacak bir şey yok: Yardımcıyı gönder'e bas, bu uygulama eşleşen yardımcıyı konsola gönderir. O zamana kadar yeni sürümün düzeltmeleri ve özellikleri çalışmaz.",

"joberr.direct_staged_file_missing": "Bu yükleme zaten tamamlanmıştı, dolayısıyla yayımlanacak bir şey kalmamıştı — üstelik PS5'teki dosya şu anda yok ya da boyutu yanlış. Dosyayı yeniden yükleyin ve «Sürdür» yerine «Üzerine yaz» seçeneğini kullanın.",
"joberr.direct_tx_corrupt": "PS5 bu aktarımda protokol bozulması algıladı. «Payload gönder» sekmesinden payload'ı yeniden başlatıp tekrar deneyin.",
"joberr.direct_writer_io_error": "Dosya yazılırken PS5'in boş alanı tükendi (ya da harici sürücü çıkarıldı). Hedef sürücüde yer açıp «Yeniden dene»ye tıklayın — yükleme kaldığı yerden devam eder.",
"joberr.fs_delete_path_not_allowed": "PS5 bu yola erişimi reddetti. /data/, /user/ ya da bağlanmış bir /mnt/ext*, /mnt/usb* yolu kullanın.",
"joberr.fs_read_path_not_allowed": "Bu dosya normalde engellenen, salt okunur bir sistem bölümünde. /system, /system_data ve diğer korumalı yollardan indirmek için Ayarlar → «Sistem dosyalarının indirilmesine izin ver» seçeneğini açın.",
"joberr.fs_write_failed": "PS5 aktarım sırasında hedefe yazamadı — çoğunlukla sürücü dolmuştur ya da harici sürücü çıkarılmıştır. Boş alanı kontrol edin veya sürücüyü yeniden takın, ardından «Yeniden dene»ye tıklayın (yükleme kaldığı yerden devam eder).",
"joberr.fs_write_failed_no_space": "Hedef sürücüde yer kalmadı (ya da dosya bu dosya sistemi için fazla büyük). PS5'te veya harici sürücüde yer açın — ya da başka bir hedef seçin — sonra «Yeniden dene»ye tıklayın.",
"joberr.packed_unsupported": "PS5 yardımcısı paketlenmiş bir aktarımı reddetti. Bu, klasör yüklemesi tek bir küçük dosyaya indiğinde (örneğin çok sayıda ufak dosyası olan bir oyunu sürdürürken) eski bir payload ile olur. ps5upload'ı en son sürüme güncelleyin, «Payload gönder» sekmesinden payload'ı yeniden gönderin ve tekrar deneyin.",
"joberr.preflight_insufficient_space": "Hedef sürücüde bu dosya için yeterli boş alan yok. PS5'te yer açın (Ayarlar → Depolama) ya da başka bir hedef seçin, sonra «Yeniden dene»ye tıklayın.",
"joberr.size_mismatch": "Aktarım kesintiye uğramadan önce tamamlanamadı — PS5'teki bir dosya eksik olduğu için yayımlanmadı (varsa eski kopyanıza dokunulmadı). Bu genellikle yükleme sırasında PS5'in dinlenme moduna geçtiği ya da elektriğinin kesildiği anlamına gelir. Konsolu uyanık tutun (Ayarlar → Sistem → Güç Tasarrufu → PS5'in Kapanmasına Kalan Süre) ve bu öğeyi yeniden çalıştırın: «Sürdür» yalnızca eksik dosyaları yeniden gönderir, «Üzerine yaz» ise temiz bir kopya oluşturur.",
"joberr.ava1_stalled": "Aktarım ilerlemeyi durdurdu (kaynak veri göndermeyi bıraktı). Yeniden dene; tekrarlanırsa kaynak sürücüyü veya ağ paylaşımını kontrol et.",
"joberr.tx_table_full": "PS5'te aynı anda çok fazla aktarım sürüyor. Bir kısmının bitmesini bekleyin ya da payload'ı yeniden başlatın.",
"joberr.zip_unsupported": "Bu .zip, yükleyicinin akış olarak gönderemeyeceği bir özellik kullanıyor (şifreleme, Deflate veya Stored dışında bir sıkıştırma yöntemi ya da güvensiz veya yinelenen bir dosya yolu). Bilgisayarınızda açın ve klasörü yükleyin.",
"joberr.sevenz_unsupported": "Bu .7z, yükleyicinin akış olarak gönderemeyeceği bir sıkıştırma yöntemi veya özellik kullanıyor. Bilgisayarınızda açın ve klasörü yükleyin.",
"joberr.sevenz_unsupported_layout": "Bu .7z, tek bir katı blok içinde dosyalarının arasında klasörler veya boş dosyalar barındırıyor; yükleyici bu düzeni akış olarak gönderemez. 7-Zip ile yeniden paketleyin ya da açıp klasörü yükleyin.",
"joberr.rar_unsupported": "Bu .rar, yinelenen veya güvensiz dosya yolları ya da yükleyicinin akış olarak gönderemeyeceği bir özellik içeriyor. Bilgisayarınızda açın ve klasörü yükleyin.",
"pkg.patch_did_not_apply": "PS5 bu güncellemeyi kabul etti ve ardından onunla hiçbir şey yapmadı — oyun hâlâ önceki sürümde. Bu, konsolun güncellemeyi kurulu ana oyunla eşleştiremediği anlamına gelir. Ana oyunu, bu güncellemeye ait ana paketten ps5upload ile yeniden kurun («Üzerine yaz» seçin), sonra güncellemeyi tekrar uygulayın.",
"pkglib.updateBaseUnknown.title": "Bu güncelleme uygulanmayabilir",
"pkglib.updateBaseUnknown.installAnyway": "Yine de kur",
"pkglib.updateBaseUnknown.body": "{id} kurulu, ancak ps5upload'ın kurduğu bir ana paketten gelmiyor — bu yüzden PS5 bu güncellemeyi onunla eşleştiremeyebilir. Böyle olduğunda konsol başarı bildirir ve hiçbir şeyi değiştirmez. Sonrasında oyun eski sürümde kalırsa, uygun ana paketi ps5upload ile kurun («Üzerine yaz» seçin) ve güncellemeyi tekrar uygulayın.",
"pkg.patch_regressed": "Bu güncellemeyi yeniden uygulamak onu kaldırdı — oyun temel sürümüne döndü. PS5’in yükleyicisi yeniden uygulanan bir güncellemeyi geri alınacak bir güncelleme olarak görür. Güncellenmiş sürüme dönmek için güncellemeyi bir kez daha uygula ve oyunda zaten var olan bir güncellemeyi yeniden kurmaktan kaçın.",
"sdk_patch_libc": "libc.prx dosyasını da yamala",
"sdk_patch_libc_hint": "Bazı geriye taşınmış oyunların ihtiyaç duyduğu, bazılarının ise açılmasını engelleyen bir uyumluluk düzenlemesi. Oyun onsuz başlamıyorsa açın, aksi halde kapalı bırakın.",
"pack_disclosure": "İndirilmiş bir geri taşıma paketiniz mi var? Onun yerine onu kurun…",
"pack_title": "Geri taşıma paketi kur",
"pack_body": "fakelib/, önceden yamalanmış bir eboot.bin ve sce_module/ içeren indirilmiş bir paket klasörü. Değiştirilen her şey önce yedeklenir, bu yüzden Geri al oyunu eski haline döndürür.",
"pack_path_placeholder": "Paketin bulunduğu klasör",
"pack_browse": "Seç…",
