"fpkg.about": "Bir oyun klasörünü ya da .exfat veya .ffpkg bağlama görüntüsünü göster. Dönüştürücü ağacı okur, başlatılabilir bir paketin ihtiyaç duyduğu her şeyin olduğunu kontrol eder ve çıktı klasörüne debug biçiminde bir .pkg yazar.",
"fpkg.aboutWhere": "Dönüştürme konsolda değil, motoru barındıran makinede çalışır — bu bilgisayar, bir Docker ana makinesi ya da bir Android cihaz. Paketi kurana kadar konsola hiçbir şey ulaşmaz — bu bilgisayardan akışla ya da önce PS5'e yüklenerek.",
"fpkg.aboutSource": "Kaynak, şifresi zaten çözülmüş bir oyun ağacı olmalı. Bir retail kurulum burada açılamaz ve seçtiğin buysa aşağıdaki kontrol bunu söyler.",
"fpkg.aboutChecks": "Kontrolün aradıkları",
"fpkg.checkEboot": "Ağacın kökünde bir eboot.bin — oyun modülü. Ham bir ELF ya da sarılmış bir SELF olmalı; retail imzalı bir modül yeniden paketlenemez.",
"fpkg.checkParam": "sce_sys/param.json olmalı ve sce_sys/param.sfo olmamalı — param.sfo, konsolun başlatma yolunu PS4 rotasına yollar.",
"fpkg.checkIcons": "36 karakterlik bir içerik kimliği, iki simge ve haklar modülü sce_sys/about/right.sprx.",
"fpkg.checkDrm": "Paketin DRM değerinin standart olması. Ücretsiz ya da yükseltilebilir bir değer konsolun oyunu kilitlemesine yol açar; yalnızca pakette yeniden yazılır, kendi dosyana asla dokunulmaz.",
"payloads_essentials_title": "ps5upload ile birlikte önerilenler",
"payloads_essentials_body": "Bir konsolu ilk kez kuruyorsan, bu üçü ps5upload'un beklediği şeylerin çoğunu karşılar: kstuff-lite (homebrew'un çoğunun dayandığı çekirdek yamaları), ShadowMount+ (depolamadaki oyun görüntülerini bağlar) ve nanoDNS (konsolu Sony'nin güncelleme yolundan uzak tutar). Bu listedeki diğer her şey isteğe bağlıdır.",
