"backport_verify_unpatched": "Bu oyun geri taşınmamış",
"backport_verify_unpatched_body": "eboot'u hâlâ orijinal SDK sürümünü taşıyor, bu yüzden hangi kütüphaneler kurulu olursa olsun bu yazılımda çalışamaz — sorun kütüphane seti değil. Geri taşımayı yeniden çalıştır; tekrar olursa SDK yaması tutmuyor demektir.",
