"joberr.ava1_refused": "PS5 bu isteği reddetti (kod {code}). Yeniden deneyin; tekrar ederse yardımcıyı ve uygulamayı aynı sürüme güncelleyin ve kodu hata raporuna ekleyin.",
"joberr.ava1_busy": "PS5 yardımcısı meşgul ve bu aktarımı zamanında kabul etmedi. Diğer işi bitene kadar bekleyin, sonra Yeniden dene'ye tıklayın.",
"joberr.ava1_unreachable": "PS5'e ulaşılamadı. Açık olduğunu, aynı ağda olduğunu ve yardımcının çalıştığını kontrol edin, sonra Yeniden dene'ye tıklayın.",
"joberr.ava1_exists": "Hedef PS5'te zaten var. Değiştirmek için Üzerine yaz'ı seçin veya başka bir hedef seçin.",
"joberr.ava1_commit_exists": "Dosya yüklendi ancak hedef zaten var olduğu için yayımlanamadı. Değiştirmek için Üzerine yaz'ı seçin veya başka bir hedef seçin.",
"joberr.ava1_cross_device": "Hedef, hazırlık alanından farklı bir sürücüde olduğu için PS5 dosyayı taşıyamadı. Aynı sürücüde bir hedef seçin veya önce dahili sürücüye yükleyin.",
"joberr.ava1_wrong_console": "Bu adresteki cihaz, bu uygulamanın eşleştiği PS5 değil. Adresi kontrol edin veya bu konsolla yeniden eşleştirin.",
"joberr.ava1_no_identity": "Bu uygulamanın henüz bir eşleştirme kimliği yok. Bağlantı ekranından PS5 ile eşleştirin ve yeniden deneyin.",
"joberr.zip_read_error": ".zip okunamadı (dosya veya sürücüsü okuma sırasında kaybolmuş olabilir). Kaynağın hâlâ bağlı olduğunu kontrol edin, sonra Yeniden dene'ye tıklayın.",
"joberr.ava1_zip_corrupt": "Bu .zip okunamadı: bozuk veya eksik. Yeniden indirin ya da yeniden oluşturun, sonra tekrar deneyin.",
"joberr.ava1_7z_corrupt": "Bu .7z okunamadı: bozuk veya eksik. Yeniden indirin ya da yeniden oluşturun, sonra tekrar deneyin.",
"joberr.ava1_7z_encrypted": "Bu .7z şifreli ve akış olarak gönderilemez. Bilgisayarınızda çıkarın ve bunun yerine klasörü yükleyin.",
"joberr.ava1_7z_unsafe_path": "Bu .7z güvenli olmayan bir dosya yolu içeriyor (kendi klasörünün dışına çıkıyor). Bilgisayarınızda çıkarın ve bunun yerine klasörü yükleyin.",
"joberr.rar_password": "Bu .rar bir parola gerektiriyor veya girilen parola yanlıştı. Doğru parolayı girin ve yeniden deneyin.",
"joberr.rar_corrupt": "Bu .rar bozuk veya bazı parçaları eksik ya da sırasız. Tüm parçaların mevcut olduğundan emin olun, sonra yeniden deneyin.",
"joberr.ava1_copy_lost": "PS5 bu kopyalamanın izini kaybetti (yardımcı yeniden başladı veya bağlantı koptu). Yeniden başlatmak için Yeniden dene'ye tıklayın.",
"joberr.ava1_copy_failed": "PS5 kopyalamayı tamamlayamadı. Boş alanı ve kaynak ile hedefin hâlâ kullanılabilir olduğunu kontrol edin, sonra yeniden deneyin.",
"joberr.ava1_local_io": "Bu bilgisayar indirilen dosyayı yazamadı. Hedef klasörün izinlerini ve boş alanını kontrol edin, sonra yeniden deneyin.",
"joberr.ava1_bad_manifest": "PS5, bu uygulamanın anlayamadığı bir dosya listesi gönderdi. Yardımcıyı ve uygulamayı aynı sürüme güncelleyin, sonra yeniden deneyin.",
"joberr.helper_not_ava1": "PS5 yardımcısı çalışmıyor. Bağlantı ekranından gönderin (banner sunuyorsa Yardımcıyı güncelle'yi kullanın), sonra yeniden deneyin.",
"joberr.helper_not_ava1_web": "PS5 yardımcısı çalışmıyor. Bu web arayüzü onu gönderemez: ps5upload payload'ını her zamanki payload yükleyicinizle konsolda başlatın (banner sunuyorsa Yardımcıyı güncelle'yi kullanın), sonra yeniden deneyin.",
"joberr.not_paired": "Bu PS5 henüz bu uygulamayı kabul etmedi. İkisini eşleştirin (Eşleştir… düğmesi), sonra yeniden deneyin.",
