volumes_pkg_copies_hint: "Bu seçim ne yapar: “Yükle ve kur” önce .pkg dosyasını PS5'e kopyalar, sonra o kopyadan kurar. Burada yalnızca bu kopyaların hangi sürücüde duracağı belirlenir. Oyunların nereye kurulduğunu değiştirmez (buna PS5 kendi Depolama ayarlarında karar verir) ve “Akışla kur” hiç kopya tutmaz. Seçilen sürücü bağlı değilse kopyalar dahili depolamaya gider.",
