"arcpkg.choose": "Arşiv seç…",
"arcpkg.help": "Herhangi bir klasörde bir veya daha fazla .pkg dosyası içeren .zip, .7z veya .rar için. Yalnızca paketler, doğrudan PS5'e açılır (bu bilgisayara hiçbir şey çıkarılmaz), ardından sırayla kurulur: önce ana oyun, sonra güncellemesi, sonra DLC. Çok parçalı RAR (.part1.rar, .part2.rar…) desteklenir: ilk parçayı seçin ve diğerlerini yanında tutun. RAR parola gerektirdiğinde sorulur; parolalı ZIP ve 7z desteklenmez.",
"arcpkg.keepsRunning": "Başka bir ekran açsanız da çalışmaya devam eder ve Görevler'de de görünür.",
"arcpkg.notArchive": "Bu dosya bir .zip, .7z veya .rar arşivi değil.",
