"arcpkg.title": "Arşivden paket kur",
"install.library.title": "PS5'teki paket kopyaları",
"install.stream.file.help": "Bir .pkg veya .fpkg seçin ya da bu pencerenin herhangi bir yerine bırakın. Kurulum bitene kadar uygulamayı açık tutun; ilerleme yukarıdaki kuyrukta ve Görevler'de görünür.",
"install.stream.file.title": "Paket dosyası kur",
"install.tab.stream.lead": "PS5 doğrudan bu bilgisayardan veya bir bağlantıdan kurar. Önce PS5'e kopya konmaz, bu yüzden orada boş alan gerekmez ve en güvenilir kurulum yolu budur.",
"install.tab.upload.lead": "Paket önce PS5'e kopyalanır, sonra o kopyadan kurulur. PS5 bu bilgisayara ulaşamadığında (akış ağ hatasıyla başarısız olduğunda) veya paketleri PS5'te tutup daha sonra bu bilgisayar olmadan yeniden kurmak istediğinizde kullanın.",
"install.upload.file.browser": "Buradan PS5'e paket kopyalamak için masaüstü uygulaması gerekir. Web arayüzünde Akışla kur'u kullanın veya aşağıdan zaten PS5'te olan paketleri kurun.",
"install.upload.file.help": "Bir .pkg veya .fpkg seçin. Kopya için PS5'te paketin tamamı kadar boş alan gerekir ve siz silene kadar aşağıdaki listede kalır.",
"install.upload.file.title": "Paketi PS5'e kopyala ve kur",
"linkcard.confirm.direct": "PS5 paketi bağlantıdan kendisi indirir ve kurar. Başladıktan sonra bu bilgisayara gerek kalmaz ve ilerleme burada değil, PS5'te (İndirilenler) görünür. PS5 bağlantıya ulaşamazsa uygulama bunun yerine bu bilgisayar üzerinden aktarır. Kurulu bir oyunun üzerine yeniden kurmak, Sony'nin kurucusu başarısız olursa o oyunu silebilir. Yalnızca güvendiğiniz ve kurma hakkınız olan paket bağlantılarını kullanın.",
"linkcard.confirm.download": "Bu bilgisayar önce paketin tamamını diske kaydeder, sonra PS5'e kurar. İki adım da bitene kadar açık kalmalı ve paket için boş alanı olmalıdır. Kurulu bir oyunun üzerine yeniden kurmak, Sony'nin kurucusu başarısız olursa o oyunu silebilir. Yalnızca güvendiğiniz ve kurma hakkınız olan paket bağlantılarını kullanın.",
"linkcard.confirm.stream": "Bu bilgisayar paketi indirir ve doğrudan PS5'e aktarır, bu yüzden kurulum bitene kadar açık ve bağlı kalmalıdır. Diske hiçbir şey kaydedilmez. Kurulu bir oyunun üzerine yeniden kurmak, Sony'nin kurucusu başarısız olursa o oyunu silebilir. Yalnızca güvendiğiniz ve kurma hakkınız olan paket bağlantılarını kullanın.",
