stop: "Durdur",
activity_description_v2: "Uygulamanın konsollarınızda yaptığı ve yapmış olduğu her şey: yüklemeler, indirmeler, kurulumlar ve dosya işlemleri. Herhangi birini buradan durdurabilir veya yeniden deneyebilirsiniz. Son 100 tanesi, yeniden başlatmalardan sonra da saklanır.",
fw_spoof_subtitle_v2: "Bu PS5'in bildirdiği yazılım sürümünün bir spoof payload'u tarafından değiştirilip değiştirilmediğini denetler; böylece sürüme bağlı bir şey kurmadan önce gerçek sürümü bilirsiniz.",
health_subtitle_v2: "PS5'in, bu uygulamanın ve aralarındaki ağın çalıştığını denetler, çalışmıyorsa neyi düzeltmeniz gerektiğini söyler ve aralarındaki dosya aktarım hızını ölçer.",
remotePlay_subtitle_v2: "Bu PS5'i Remote Play için ayarlayın ve PS Remote Play uygulamasını ona bağlayan PIN'i alın.",
saves_description_v2: "PS5'teki kayıt verileri, oyun başına bir girdi. Bir oyunun kayıtlarını bu bilgisayarda bir .zip dosyasına yedekleyin ve daha sonra geri yükleyin.",
shell_description_v2: "PS5'te yardımcı işlemin içinde çalışan komutlar yazın. İleri düzey kullanıcılar içindir. Çıktı komut başına 256 KB ile sınırlıdır; yukarı ve aşağı oklar önceki komutları geri getirir.",
"arcpkg.links.go": "{count} dosyayı indir",
"arcpkg.links.help": "Arşive veya bölünmüş bir arşivin her parçasına giden doğrudan bağlantıyı, her satıra bir tane olacak şekilde yapıştırın. Dosyalar bu bilgisayara (Downloads/ps5upload) indirilir ve hepsi için yer gerekir; ardından içlerindeki paketler yukarıda anlatıldığı gibi PS5'e açılır.",
"arcpkg.links.kept": "İndirilen {count} dosya {dir} konumunda. Kurulumu yeniden deneyebilmeniz için saklanırlar; işiniz bitince silin.",
"arcpkg.links.progress": "{count} dosyadan {n}. dosya bu bilgisayara indiriliyor…",
