connection_payload_engine_unreachable: "Uygulama bu bilgisayardaki kendi motoruna ulaşamadı, bu yüzden yardımcının PS5'te başlayıp başlamadığını bilemiyor. Bu bir PS5 sorunu değil: pencerenin üstündeki uyarı nedenini söyler ve motoru yeniden başlatabilir. Ardından Yardımcıyı gönder'e yeniden basın. ({error})",
"engine_problem.missing.fix": "ps5upload-engine'i virüs programınızın karantinasından geri yükleyin (ya da izin verin) veya uygulamayı yeniden kurun.",
"engine_problem.missing.why": "Motor programı uygulamanın klasöründe yok. Güvenlik yazılımları bazen onu karantinaya alır.",
"engine_problem.port.fix": "Motoru yeniden başlat'a basın. İşe yaramazsa ps5upload-engine'e güvenlik duvarında veya virüs programında izin verin, sonra uygulamayı yeniden başlatın.",
"engine_problem.port.why": "Bir şey motorun adresini ({url}) tutuyor ama yanıt vermiyor: o bağlantı noktasındaki başka bir program ya da bağlantıları engelleyen bir güvenlik yazılımı.",
"engine_problem.proxy.fix": "Yerel adresler (127.0.0.1) için proxy'yi veya VPN aracını kapatın ya da uygulamayı http_proxy / ALL_PROXY ayarı olmadan başlatın.",
"engine_problem.proxy.why": "Motora giden istekler motor yerine bu bilgisayarda ayarlı bir proxy'ye gitti.",
"engine_problem.remote.fix": "Motorun (Docker kapsayıcısı veya başka bir bilgisayar) çalıştığını ve o adresten erişilebildiğini denetleyin ya da adresi Ayarlar'dan değiştirin.",
"engine_problem.remote.why": "Bu uygulamanın kullanacağı motor ({url}) yanıt vermiyor.",
"engine_problem.restart": "Motoru yeniden başlat",
"engine_problem.slow.fix": "Motoru yeniden başlat'a basın. Yerel bağlantıları süzen güvenlik duvarı veya virüs programı da buna yol açabilir: ps5upload-engine'e izin verin.",
"engine_problem.slow.why": "Motor çalışıyor ama yanıt vermiyor.",
"engine_problem.stopped.fix": "Motoru yeniden başlat'a basın. Yeniden durursa Günlükler ekranı nedenini gösterir.",
"engine_problem.stopped.why": "Motor çalışmıyor: durdu ya da hiç başlamadı.",
"engine_problem.title": "Uygulama bu bilgisayardaki motoruna ulaşamıyor",
"engine_problem.web.fix": "Sunucunun (Docker kapsayıcısı) çalıştığını denetleyin, sonra bu sayfayı yeniden yükleyin.",
"engine_problem.web.why": "Bu sayfa, geldiği ps5upload sunucusuyla bağlantısını kaybetti.",
gate_engine_down_body_v2: "Bu ekranın uygulamanın motoruna ihtiyacı var, ama motor yanıt vermiyor. Pencerenin üstündeki uyarı nedenini söyler ve onu yeniden başlatabilir.",
"profile.np.body": "PS5'in, Sony'ye bağlanmadan, giriş yapmış hesabı PlayStation Network'e girişli saymasını sağlar. Konsolun bazı özellikleri yalnızca girişli bir hesaba açılır; Remote Play de bunlardan biridir. earthonion'ın np-fake-signin'ini kullanır; düğmeye bastığınızda proje sayfasından indirilir.",
"profile.np.confirm_title": "Bu hesapla giriş yapılsın mı?",
"profile.np.failed": "Giriş çalışmadı",
"profile.np.fetching": "np-fake-signin alınıyor…",
"profile.np.sending": "PS5'e gönderiliyor…",
"profile.np.sent": "np-fake-signin {version} PS5'te çalıştı. Bitirmek için PS5'i yeniden başlatın; ardından hesap girişli görünür ve Ayarlar > Sistem > Remote Play açılabilir.",
"profile.np.sign_in": "Giriş yap",
"profile.np.state_loading": "Hesap okunuyor…",
"profile.np.state_no_slot": "Yukarıdaki hesapların hiçbirinin adı {user} değil, bu yüzden np-fake-signin durur. Hesaba giriş yapmış kullanıcıyla aynı adı verin ya da onun için bir hesap etkinleştirin.",
"profile.np.state_no_user": "PS5'te giriş yapmış kullanıcı yok. İstediğiniz profile giriş yapıp geri gelin.",
"profile.np.state_not_activated": "{user} (hesap {slot}) için henüz hesap kimliği yok. Önce yukarıdaki Hesaplar bölümünden etkinleştirin.",
"profile.np.state_ready": "Hazır: {user} (hesap {slot}) etkin.",
"profile.np.step_activate": "Hesabın bir hesap kimliği olmalı. PSN'e bağlı bir hesapta vardır; yoksa yukarıdaki Hesaplar bölümünden etkinleştirin (çevrimdışı etkinleştirme).",
"profile.np.step_run": "O kullanıcı PS5'te girişliyken Giriş yap'a basın. Bir kez çalışır ve kapanır.",
"profile.np.title": "PlayStation Network'e giriş (çevrimdışı)",
