"collection.permanent_delete_hint": "Bu motorda çöp sepeti yok (Docker veya masaüstü olmayan bir sunucu). Açıkken bir kopya Koleksiyon'dan silinebilir: kalıcı olarak gider ve her seferinde onaylarsın.",
