"pkg.sony_80b21104": "PS5 bu paketi kabul etmedi (0x80B21104). Başka paketler bu konsola yükleniyorsa sorun bu dosyadadır: çoğunlukla bu konsolun yazılımının anladığından daha yeni araçlarla yapılmış yeni bir oyunun paketi ya da sahte imzalı (FPKG) olmayan bir paket. Yazılımına uygun yapılmış bir paket (backport) kullan veya oyunu yükleyiciyi atlayan bir yolla yükle: oyun klasörünü ya da ShadowMount+ için bir oyun imajını (.exfat veya .ffpfsc) Yükle ile kopyala.",
