sendpayload_probe_invalid_ext: "Yük bir .elf, .bin, .js, .lua veya .jar dosyası olmalıdır.",
sendpayload_probe_no_signature: "PS5Upload imzası bulunamadı — yalnızca bu yüke güveniyorsanız kullanın.",
