sendpayload_probe_too_small: "Bu dosya boş, gönderilecek bir şey yok.",
servers_subtitle: "NAS'larınız ve sunucularınız (SMB, FTP, FTPS, SFTP/WebDAV). Bir oyun veya dosya için göz attığınız her yerde, Gözat'ın yanındaki ▾ ile bunlardan seçin.",
settings_artwork_cache_explain_v2: "Oyun kapakları motorun çalıştığı yerde (bu bilgisayarda veya web sürümü için sunucuda) tutulur, böylece her seferinde PS5'inizden okunmak yerine anında yüklenir. Otomatik olarak yenilenir ve bir konsolda oyun kurduğunuzda veya kaldırdığınızda o konsol için silinir.",
settings_backup_downloaded: "{name} indirildi",
settings_backup_hint_v2: "Temayı, PS5 listesini, bildirim geçmişini, etkinlik kaydını ve diğer tercihleri tek bir JSON dosyasında toplayın; uygulamanın depolamasını sildikten sonra veya başka bir makinede geri yüklemek için. Konsol eşleştirmeleri, Koleksiyon, kayıtlı sunucuların parolaları ve geri taşıma kütüphaneleri dahil değildir.",
settings_backup_restored: "{count} ayar geri yüklendi. Tüm değişikliklerin etkili olması için uygulamayı yeniden başlatın.",
settings_backup_saved: "{path} konumuna kaydedildi",
settings_card_console_rest: "Dinlenme modu",
settings_card_console_connect: "Bağlanma",
auto_bringup_label: "Otomatik başlat",
auto_bringup_hint: "Kayıtlı bir PS5'in yükleyicisi (elfldr, port 9021) açık ve yardımcı çalışmıyorken uygulama hızlı başlatmayı kendisi yapar: ayarladıysanız başlatma oynatma listeniz, ardından yardımcı, ardından otomatik yükleyici oynatma listeniz. Konsol her açıldığında bir kez; dinlenme modundan sonra yalnızca yardımcı yeniden gönderilir. Konsolun kendi otomatik yükleyicisi önce bitsin diye yükleyici göründükten sonra yaklaşık 90 saniye bekler. Varsayılan olarak kapalıdır.",
bringup_auto_hint_short: "PS5'in yükleyicisi açık ve yardımcı kapalıyken bunu kendisi çalıştırır, yükleyici göründükten yaklaşık 90 saniye sonra. Konsol her açıldığında bir kez.",
settings_card_install_fallback: "PS5 bir paketi alamadığında",
settings_card_system_files: "Sistem dosyaları",
settings_file_hint_v2: "Ana tercihler (tema, dil, motor, kayıt yolu, yükleme varsayılanları, erişilebilirlik, kenar çubuğu) bu JSON dosyasına yansıtılır. Elle düzenleyebilirsiniz; düzenlemeler uygulamayı bir sonraki açışınızda geçerli olur. Her şeyi içermez: tüm tercihlerinizi taşımak için Yedekle / geri yükle'yi kullanın.",
settings_group_console: "Konsol",
