settings_schedule_label_placeholder_v2: "Etiket (ör. kayıtları yedekle)",
settings_updates_browser_note: "Bu web sayfası ps5upload motoru tarafından sunulur ve onunla birlikte güncellenir: yeni Docker imajını çekin (veya sunucunuzdaki motoru güncelleyin) ve yeniden başlatın.",
"show_file_list_hint_v2": "Yüklenen dosyaları ilerleme çubuğunun altında listele. Binlerce dosyalı klasörlerde liste kalabalık geliyorsa kapat — genel ilerleme, hız ve kalan süre yine görünür.",
