"installed_uninstall_no_copy": "Bu bilgisayardaki Koleksiyonunuzda bu oyunun kopyası yok: kaldırmadan önce paketini bir yerde saklayın.",
"connection_send_payload_moved": "Başka bir payload (kstuff, etaHEN, herhangi bir .elf) mı göndereceksiniz? Bu, Payload'lar → Payload gönder altında. Bu ekran yalnızca PS5Upload yardımcısını gönderir.",
"connection_send_payload_open": "Payload gönder'i aç",
"upload_elf_title": "Bu bir oyun değil, bir payload (.elf)",
"upload_elf_body": "Yüklemek yalnızca dosyayı kopyalar. ShadowMount+ oyun klasörlerini (eboot.bin ve sce_sys içeren) ve oyun imajlarını alır, asla bir .elf'i almaz; bu yüzden ana ekranda görünmez. Çalıştırmak için onu konsolun yükleyicisine gönderin. Yüklenmesi gereken, .ffpkg veya .exfat imajı ya da eboot.bin içeren bir klasör olarak gelen homebrew uygulamasıdır.",
"netdoctor.hint.below_test": "Bu yükleme {speed} hızında, hız testinin ölçtüğü {expected} değerinin çok altında.",
"netdoctor.hint.runs_at": "Bu yükleme {speed} hızında.",
"netdoctor.hint.cause_source": "Onu yavaşlatan ağ değil, bu bilgisayardaki dosyaların okunması: bir USB sürücü ya da sabit disk, bir ağ paylaşımı (NAS) veya bir arşivin açılması bağlantıdan yavaştır. Oyunu önce dahili bir SSD'ye kopyalamak ya da arşivin dosyalarını açtıktan sonra yüklemek tam hız sağlar.",
"netdoctor.hint.cause_disk": "Onu yavaşlatan ağ değil, PS5'in sürücüsü: harici bir USB sürücü, neredeyse dolu bir sürücü veya binlerce küçük dosya (her biri kendi süresini alır) bağlantının ilettiğinden daha yavaş yazar. Bir oyun imajı (.ffpkg veya .exfat) tek dosya olarak gider.",
"netdoctor.hint.cause_workers": "PS5 hâlâ aldığını yazıyor, ağı beklemiyor. Çok sayıda küçük dosyada her biri kendi süresini alır; bir oyun imajı (.ffpkg veya .exfat) tek dosya olarak gider.",
"netdoctor.hint.cause_cap": "Onu yavaşlatan yükleme hızı sınırı (yaklaşık {cap} MiB/sn, bu ekranda ve Ayarlar'da). Kaldırmak için 0 yapın.",
"profile.np.confirm_body_v2": "np-fake-signin, {user} için PlayStation Network giriş dosyalarını ve ayarlarını PS5'e yazar. Sony'ye hiçbir şey gönderilmez. Ardından PS5'i yeniden başlatın.",
"profile.np.side_effect": "Bilinen yan etki: sonrasında bazı konsollar herhangi bir oyun açılmadan önce \"PS5 Konsol Kısıtlamalarını Geçici Olarak Devre Dışı Bırak\" ister ve Ayarlar > Kullanıcılar ve Hesaplar > Diğer > Oturumu Kapat gri kalabilir. Uygulama np-fake-signin'in PS5'te değiştirdiği her şeyin bir kopyasını önce saklar, bu yüzden buradaki Girişi geri al hepsini geri yükler.",
"profile.np.backing_up": "Hesabın mevcut ayarlarının bir kopyası PS5'te saklanıyor…",
"profile.np.backup_failed": "PS5 hesabın ayarlarının bir kopyasını saklayamadı, bu yüzden np-fake-signin çalıştırılmadı. Yardımcıyı bu uygulamanın sürümüyle değiştirip yeniden deneyin. ({error})",
"profile.np.step_restart_v2": "PS5'i yeniden başlatın. Daha sonra geri almak için buradan Girişi geri al'a basın ve yeniden başlatın.",
"profile.np.undo": "Girişi geri al",
"profile.np.undo_hint": "Bu hesabın girişten önceki ayarlarının bir kopyası PS5'te saklanıyor; bu onu geri yükler.",
"profile.np.undo_confirm_title": "Giriş geri alınsın mı?",
"profile.np.undo_confirm_body": "{user} kullanıcısının ayarlarını ve dosyalarını np-fake-signin çalışmadan önceki hâline getirir. Ardından PS5'i yeniden başlatın. Remote Play dahil, giriş yapılmış hesap gerektiren özellikler yeniden giriş yapana kadar açılmayabilir.",
"profile.np.undoing": "Ayarlar geri yükleniyor…",
"profile.np.undone": "Geri yüklendi ({count} ayar ve dosya). Bitirmek için PS5'i yeniden başlatın.",
"profile.np.no_backup": "Bu hesapta np-fake-signin'in şablon ayarları var (doğum tarihi 1983-04-12, çevrimdışı yetişkin işareti kapalı) ve bu PS5'te öncesinden bir kopya yok, bu yüzden uygulama bunu geri alamaz. PS5 artık oyunlar açılmadan önce konsol kısıtlamalarını geçici olarak devre dışı bırakmayı istiyorsa: Ayarlar > Aile ve Ebeveyn Denetimleri > PS5 Konsol Kısıtlamaları (değiştirmediyseniz parola 0000) ve kısıtlamaları orada kaldırın.",
