"rp_running_elsewhere_body": "Başka bir pencereden ya da bu sayfa yenilenmeden önce başlatıldı ve hâlâ sürüyor.",
"rpg_user_title": "PS5'te bir kullanıcıyla oturum aç",
"rpg_user_body": "Konsolda oynayacağın kullanıcıyı seç. Kimsenin ekranda kalması gerekmez ama kullanıcının oturumu açık olmalı. Giriş şifresi olmayan bir kullanıcı kullan: şifre, konsol uyandığında otomatik oturum açmayı durdurur.",
"rpg_account_title": "O kullanıcıya bir hesap kimliği ver",
"rpg_account_body": "Remote Play bir hesap kimliğiyle eşleşir. PlayStation Network'e bağlı bir kullanıcıda zaten vardır; çevrimdışı bir kullanıcı için yukarıdaki Kullanıcılar bölümünden bir tane ayarlanmalı (herhangi bir kimlik olur; not al, sonrasında yapılan kayıtlar ona bağlanır).",
"rpg_signin_title": "Hesapla PlayStation Network'e giriş yap (çevrimdışı)",
"rpg_signin_body": "PS5, Remote Play'i yalnızca girişli bir hesabın kullanmasına izin verir. Konsolun kendi Remote Play ayarı griyse aşağıdaki çevrimdışı girişi çalıştır (Sony'ye hiçbir şey gönderilmez), sonra PS5'i yeniden başlat. Geri alınabilir.",
"rpg_signin_fix": "Girişe git",
"rpg_service_title": "Remote Play'i aç",
"rpg_service_body": "Ayarlar › Sistem › Remote Play › Remote Play'i etkinleştir. Uygulama bunu senin için açabilir; 10.00 ve sonrası yazılımlarda bu kullanıcıya da izin verebilir.",
"rpg_rest_title": "PS5'in dinlenme modundan uyandırılmasına izin ver",
"rpg_rest_body": "Ayarlar › Sistem › Güç Tasarrufu › Dinlenme Modunda Kullanılabilir Özellikler: «İnternete bağlı kal» ve «PS5'i ağ üzerinden açmayı etkinleştir» seçeneklerini aç. Bunlar olmadan dinlenme modundaki konsol uyandırılamaz ve ağı birkaç saniye sonra uykuya geçer. Bunları yalnızca konsol gösterebilir.",
"rpg_pair_title": "Bu uygulamayı konsolla eşleştir",
"rpg_pair_body": "Bağlantı › Uyandır ve oturum aç › Kur. Tek tıklama bu uygulamayı PS5'e kaydeder (PS Remote Play uygulamasını eşleştirmek gibi) ve anahtarlarını bu bilgisayarda saklar. Yayın, uyandırma ve oturum açma bunların hepsini kullanır; konsolu sıfırladıktan veya kullanıcıyı değiştirdikten sonra tekrar yap.",
"rpg_play_title": "Oyna",
"rpg_play_body": "Remote Play'i aç ve Başlat'a bas: uygulama konsol dinleniyorsa uyandırır, oturum açar ve yayını başlatır. Bu bilgisayara bağlı bir kumandayla, klavyeyle ya da dokunarak oyna. Bunun yerine Sony'nin PS Remote Play uygulamasını veya chiaki-ng'yi kullanmak için aşağıdan bir PIN iste ve oraya gir.",
"rpg_play_fix": "Remote Play'i aç",
"rpg_title": "Remote Play kurulumu",
"rpg_progress": "{n} kontrol edilen adımdan {done} tanesi tamam",
"rpg_on_console": "konsolda kontrol et",
"rpg_trouble": "Hâlâ çalışmıyorsa",
"rpg_t_start_q": "Oyna ekranında Başlat soluk.",
"rpg_t_start_a": "Bu uygulama o konsolla henüz eşleşmedi: 6. adımı yap (Bağlantı › Uyandır ve oturum aç › Kur).",
"rpg_t_pair_q": "Eşleştirme kurulumu, etkin hesabı olan oturum açmış bir kullanıcı olmadığını söylüyor.",
"rpg_t_pair_a": "1. ve 2. adımlar: PS5'te bir kullanıcıyla oturum aç ve ona bir hesap kimliği ver, sonra tekrar dene.",
"rpg_t_grey_q": "PS5'in kendi Remote Play ayarı gri.",
"rpg_t_grey_a": "Hesap PlayStation Network'e giriş yapmamış. Çevrimdışı girişi çalıştır (3. adım) ve PS5'i yeniden başlat.",
"rpg_t_wake_q": "Konsol uyanmıyor ya da uyanıyor ama kullanıcı ekranında kalıyor.",
"rpg_t_wake_a": "Konsolda 5. adımı kontrol et. Giriş şifresi olan bir kullanıcı otomatik oturum açmayı durdurur. Konsol sıfırlandıysa veya kullanıcı değiştiyse eşleştirmeyi yeniden kur (6. adım).",
"rpg_t_black_q": "Görüntü siyah kalıyor, takılıyor ya da ses cızırdıyor.",
"rpg_t_black_a": "PS5 ve bu bilgisayar için kablolu bağlantı veya 5 GHz Wi-Fi kullan ve Remote Play ayarlarında 720p ya da 30 fps dene. Bu bilgisayardaki güvenlik duvarı uygulamaya yerel ağda izin vermeli (Remote Play 9295–9304 TCP ve UDP portlarını kullanır). Tarayıcıda güncel bir Chrome, Edge ya da Safari kullan: görüntü için WebCodecs gerekir.",
"rpg_t_busy_q": "PS5'in son oturumu hâlâ kapattığını ya da başka bir konsolun yayın yaptığını söylüyor.",
"rpg_t_busy_a": "Aynı anda tek konsol yayın yapar ve PS5'in bir oturum bittikten sonra 30 saniyeye kadar zamana ihtiyacı olur. Diğer yayını durdur, biraz bekle, sonra yeniden Başlat'a bas.",
"rpg_t_restrict_q": "Çevrimdışı girişten sonra oyunlar konsol kısıtlamalarını devre dışı bırakmayı istiyor.",
"rpg_t_restrict_a": "Bu sayfada Girişi geri al'ı kullan ve yeniden başlat ya da kısıtlamayı Ayarlar › Aile ve Ebeveyn Denetimleri › PS5 Konsol Kısıtlamaları altında kaldır (değiştirmediysen parola 0000).",
