"send_title_v2": "Yükle ve Kur",
"collection.send_many_body_v2": "Her PS5 eksik olanı alır: oyunun paketi ya da klasörü, imajı veya arşivi, artı sahip olduğu oyunlar için daha yeni güncellemeler ve DLC'ler. Paketler bu bilgisayardan akıtılır; geri kalanı «Yükle ve Kur»da ayarlı sürücüye, homebrew klasörüne yüklenir.",
"first_run_step4_body_v3": "PS5'ine .ffpkg oyun imajları içeren bir USB bellek tak, ShadowMount+ bunları otomatik bağlar — Oyunlar'da görünürler. Başka dosyalar göndermek veya .pkg paketleri kurmak için «Yükle ve Kur»u kullan.",
"first_run_go_upload_v2": "Yükle ve Kur'u aç",
"fpkg.aboutFake_v2": "Sonuç bir sahte pakettir, bu yüzden konsolun kurmadan önce sahte paket desteğini yüklemiş olması gerekir: kstuff (PS5 sahte paket destekli sürüm), a53_ppr_install_fast.elf ve shadowmountplus.elf, bu sırayla. «Yükle ve Kur» da kurulum düğmelerinin yanında aynı şeyi söyler.",
"fpkg.openUpload_v2": "Yükle ve Kur'u aç",
"connection_step3_hint_v3": "«Yükle ve Kur»u aç ve bir oyun klasörü, .exfat ya da .ffpkg imajı veya .pkg paketi bırak. Gönderdiğin imajlar ve klasörler Oyunlar'da oyunun sayfasında listelenir; orada Bağla onları PS5'in ana ekranına koyar.",
"connection_go_upload_v2": "Yükle ve Kur'u aç",
"netdoctor.speed_cap.on.fix_v2": "Gerekmiyorsa sınırı «Yükle ve Kur»da kaldır.",
"payloads_fpkg_ppr_note_v2": "Sahte paket kurmak için ayrıca bu listede olmayan a53_ppr_install_fast.elf gerekir: yayınlanmış bir indirmesi yoktur, GitHub'daki kaynak koddan derlenir. «Yükle ve Kur» sahte paketlerin ihtiyaç duyduğu her şeyi sırasıyla listeler.",
"fs_extract_next_pkgs_v2": "İçinde {n} paket var: «Yükle ve Kur»dan veya buradaki satırlarından kur.",
"game_hub_no_addons_v2": "Bu başlık için hazırlanmış DLC paketi yok. «Yükle ve Kur»dan bir tane gönder.",
"game_hub_open_install_v2": "Yükle ve Kur'u aç",
"bandwidth_cap_off_hint_v3": "Sınır yok. Yüklemeler Wi-Fi/LAN'ını doldurup diğer cihazları yavaşlatıyorsa bir sınır koy. Bir sonrakinden itibaren tüm yüklemelere uygulanır: «Yükle ve Kur», kuyruk ve Dosyalar'dan.",
"queue_links_cleared_body_v2": "Yeniden başlatmadan sonra {n} kurulum bağlantısı korunmadı — bağlantılar asla diske kaydedilmez. «Yükle ve Kur»dan yeniden ekle.",
"game_hub_no_updates_v2": "Bu başlık için hazırlanmış güncelleme paketi yok. «Yükle ve Kur»dan bir tane gönder.",
"pkglib.fpkgsupport.firmware": "PS5 sahte paketleri (PS5 FPKG), 11.60'tan sonraki yazılım sürümlerinde henüz desteklenmiyor: kurulurlar ama oyun başlamaz. PS4 sahte paketleri sorunsuzdur.",
"upload_drop_here3": "Paketleri, oyunları, disk imajlarını, arşivleri veya herhangi bir dosyayı bırak ya da seç",
"upload_pick_here_mobile3": "Paketleri, oyunları, disk imajlarını, arşivleri veya herhangi bir dosyayı seç",
"upload_drop_kind_pkg": "Paketler (.pkg, .fpkg): oyun, güncelleme veya DLC olarak kurulur; buradan akıtılır ya da önce yüklenir.",
"upload_drop_kind_game": "Oyun klasörleri ve oyun dökümleri: PS5'e kopyalanır; ana ekrana eklenebilir.",
"upload_drop_kind_image": "Disk imajları (.exfat, .ffpkg, .ffpfs, .ffpfsc): PS5'e kopyalanır; bağlanabilir.",
"upload_drop_kind_archive": "Arşivler (.zip, .7z, .rar): PS5'e ayıklanır.",
"upload_drop_kind_other": "Diğer her dosya veya klasör: olduğu gibi kopyalanır.",
"upload_other_ways": "Ya da bir paket kur:",
"queue_stream_fail_hint": "Akışla kur, PS5'in paketi bu bilgisayardan almasını sağlar. Başarısız olmaya devam ederse, PS5'in ulaşabilmesi için bu bilgisayarın güvenlik duvarında yerel ağda ps5upload'a izin ver veya paketi önce PS5'e kopyalayıp sonra kuran Yükleyerek yeniden dene seçeneğini kullan.",
"err_install_enoent_generic_v2": "Sony'nin yükleyicisi kurulum sırasında ihtiyaç duyduğu bir dosyayı açamadı (çekirdek hatası 0x80020002 = ENOENT). Bu bir DLC pkg'siyse, temel oyun henüz kurulu değil — önce temeli kur. Aksi takdirde hazırlanan paket yükleme ile kurulum arasında silinmiş olabilir; kurulumu bir kez tekrar dene. Başarısız olmaya devam ederse, «Yükle ve Kur» ekranındaki Akışla kur seçeneğiyle kur; bu seçenek paketi önce konsola kopyalamak yerine doğrudan bu bilgisayardan gönderir.",
"upload_convert_first": "Önce dönüştür",
"batch_convert_first_hint": "İşaretli oyunları, klasörleri ve imajları önce onlardan paket, imaj veya klasör oluşturmak için Atölye'de aç",
"add_sources_pick_folders": "Bir veya daha fazla klasör seç",
"add_sources_pick_files": "Bir veya daha fazla dosya seç",
"workshop_add_locked": "Bir oyun oluşturuluyor: şimdi seçilen oyunlar kuyrukta bekler.",
"workshop_add_hint": "Burada kontrol etmek için bir oyun seç. Birden çok oyun veya bir oyun klasörü kuyruğa girer ve sırayla oluşturulur.",
"workshop_description_v2": "Bir oyunun biçimini PS5'e gitmeden önce değiştir: bir paket (.pkg), bir oyun imajı (.exfat, .ffpkg ya da daha küçük .ffpfsc) veya düz bir klasör oluştur, ya da bir imajın veya paketin içine bakıp dosyalarını değiştir. İş bu bilgisayarda yapılır. Bir oyunu olduğu gibi göndermek için {send} ekranını kullan.",
"cq_title_v2": "⑤ Kuyruk",
"cq_about": "Bu bilgisayarda sırayla oluşturulur; her biri eklendiği anda ②, ③ ve ④ nasıl ayarlıysa öyle. ① altından daha fazla ekle, kuyruk çalışırken bile; bekleyen bir oyunu seçenekler düğmesiyle değiştir.",
"cq_then_send": "Kurulum veya yükleme için ayarlanan bir oyun, oluşturulunca {send} kuyruğuna geçer.",
"cq_open_send": "{send} ekranını aç",
"backup_alike_toggle": "{since} tarihinden beri {count} benzer kopya. Eski birini geri yüklemek için hepsini göster.",
"add_sources_no_picker": "Bu sürüm bu bilgisayara göz atamıyor — motorun görebildiği bir yol yazın.",
"collection.empty_body_v2": "İçindeki paketler, oyun klasörleri, oyun imajları ve arşivler bulunur ve oyuna göre gruplanır. Klasörde hiçbir şey değiştirilmez. Bu cihazdaki bir klasör, harici bir sürücü veya bir NAS ya da sunucudaki klasör (SMB, FTP, SFTP, WebDAV) olur.",
"collection.add_nas_folder": "Bir NAS veya sunucudan",
"browse_this_device": "Bu cihaz…",
"queue_added_waits_for_start": "Kuyruğa eklendi — çalıştırmak için “Kuyruğu başlat”a basın",
"queue_added_waits_for_start_body": "“Bir şey eklediğinizde kuyruğu başlat” kapalı, bu yüzden “Kuyruğu başlat”a basana kadar hiçbir şey başlamaz.",
"queue_auto_start": "Bir şey eklediğinizde kuyruğu başlat",
"queue_auto_start_tooltip": "Açık: “Kur”, “Şimdi yükle” ve “Gönder” bu konsolun tüm kuyruğunu sırayla başlatır. Kapalı: yalnızca kuyruğa eklerler ve “Kuyruğu başlat”a basana kadar hiçbir şey çalışmaz.",
"queue_auto_start_hint": "Açık: “Kur”, “Şimdi yükle” ve “Gönder” konsolun tüm kuyruğunu sırayla başlatır — yalnızca az önce eklediğinizi değil. Kapalı: yalnızca kuyruğa eklerler ve “Kuyruğu başlat”a basana kadar hiçbir şey çalışmaz. Varsayılan olarak açık.",
